"""Idea suggestions for the board (generated by ``content.ideas`` or by insights)."""

from __future__ import annotations

from typing import Annotated, Any

from fastapi import APIRouter, Query

from app.deps import CtxDep, DbDep, PageDep
from app.repositories.content import IdeaRepository
from app.schemas.assets import Page
from app.schemas.content import IdeaAcceptOut, IdeaOut, IdeasGenerateOut, IdeasGenerateRequest
from app.services import content_service

router = APIRouter(prefix="/ideas", tags=["content"])


@router.get("", response_model=Page[IdeaOut])
def list_ideas(
    ctx: CtxDep,
    db: DbDep,
    page: PageDep,
    status: Annotated[str | None, Query(pattern="^(suggested|accepted|dismissed)$")] = "suggested",
) -> dict[str, Any]:
    rows, total = IdeaRepository(db).search(
        ctx.workspace_id, status=status, limit=page.limit, offset=page.offset
    )
    return {
        "items": [content_service.idea_out(r) for r in rows],
        "total": total,
        "limit": page.limit,
        "offset": page.offset,
    }


@router.post("/generate", response_model=IdeasGenerateOut)
def generate_ideas(body: IdeasGenerateRequest, ctx: CtxDep, db: DbDep) -> dict[str, Any]:
    """Synchronous LLM call (``content.ideas``); stored with source ``twin`` and provenance."""
    return content_service.generate_ideas(db, ctx.workspace_id, body.topic, body.count)


@router.post("/{idea_id}/accept", response_model=IdeaAcceptOut)
def accept_idea(idea_id: str, ctx: CtxDep, db: DbDep) -> dict[str, Any]:
    idea, item = content_service.accept_idea(db, ctx.workspace_id, idea_id)
    return {"idea": content_service.idea_out(idea), "content_item": item}


@router.post("/{idea_id}/dismiss", response_model=IdeaOut)
def dismiss_idea(idea_id: str, ctx: CtxDep, db: DbDep) -> dict[str, Any]:
    return content_service.idea_out(content_service.dismiss_idea(db, ctx.workspace_id, idea_id))
